draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // desk
  ctx.fillStyle = '#ccc';
  ctx.fillRect(W/2-50, H/2+20, 100, 50);

  // chair
  ctx.fillStyle = '#ccc';
  ctx.fillRect(W/2-30, H/2+70, 60, 30);

  // person
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2-50+20*Math.sin(t), 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-30);
  ctx.lineTo(W/2, H/2+20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-10);
  ctx.lineTo(W/2-20, H/2+10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-10);
  ctx.lineTo(W/2+20, H/2+10);
  ctx.stroke();

  // arm moving
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-10);
  ctx.lineTo(W/2-20+10*Math.cos(t), H/2+40);
  ctx.stroke();

  // head nodding
  ctx.beginPath();
  ctx.arc(W/2, H/2-50+10*Math.sin(2*t), 20, 0, 2*Math.PI);
  ctx.fill();

  ctx.restore();
}
